<?php declare(strict_types=1); namespace Core\Http\Middleware; use Core\Auth\Auth; use Core\Contracts\MiddlewareInterface; use Core\Exceptions\AuthenticationException; use Core\Http\RedirectResponse; use Core\Http\Request; use Core\Http\Response; use Core\Http\Session; use Core\Logging\Log; final class Authenticate implements MiddlewareInterface { public function __construct( private readonly Auth $auth, private readonly Session $session, ) { } public function handle(Request $request, callable $next): Response { if (!$this->auth->check()) { Log::channel('security')->warning('Unauthenticated access attempt', [ 'path' => $request->path(), 'ip' => $request->ip(), ]); if ($request->expectsJson()) { throw new AuthenticationException(); } $this->session->flash('_intended_url', $request->path()); return new RedirectResponse(route('login')); } return $next($request); } } 